<?php
if(!defined('ABSPATH'))exit;
add_action('admin_menu',function(){add_theme_page('Fera Foundry Setup','Fera Foundry Setup','manage_options','fera-foundry','ff_setup_screen');add_options_page('Fera Foundry Connections','Fera Foundry Connections','manage_options','fera-foundry-connections','ff_connections_screen');});
add_action('admin_init',function(){
    foreach(['ff_email','ff_ai'] as $name)register_setting('ff_connections',$name,['sanitize_callback'=>function($v){return $v==='1'?'1':'0';}]);
    register_setting('ff_connections','ff_provider',['sanitize_callback'=>function($v){return $v==='gemini'?'gemini':'openai';}]);
    register_setting('ff_connections','ff_tawk_owner',['sanitize_callback'=>function($v){return in_array($v,['none','theme','external'],true)?$v:'none';}]);
    foreach(['ff_tawk_property','ff_tawk_widget','ff_google_verification','ff_bing_verification'] as $name)register_setting('ff_connections',$name,['sanitize_callback'=>function($v){return is_string($v)&&preg_match('/^[A-Za-z0-9_-]{0,200}$/D',$v)?$v:'';}]);
});
function ff_setup_screen(){
    if(!current_user_can('manage_options'))return;
    echo '<div class="wrap"><h1>Fera Solution Foundry — complete site setup</h1><p>The finalized homepage renders immediately. Activation creates separate service and demo pages without deleting old content. To make the new homepage editable in Elementor and explicitly select it in Reading settings, use the button below. This changes only the selected homepage settings; it does not replace old Elementor pages.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="ff_setup">';wp_nonce_field('ff_setup');submit_button('Use the finalized Foundry homepage');echo '</form><p>Then save Settings → Permalinks and clear Bluehost/Elementor/browser caches. Free Elementor is optional; if installed, the button enables native editing on new pages only. Review privacy/terms before launch.</p>';
    foreach(get_option('ff_pages',[]) as $slug=>$id)echo '<p><strong>'.esc_html(ff_labels()[$slug]).'</strong> — <a href="'.esc_url(get_permalink($id)).'">Open</a> · <a href="'.esc_url(get_edit_post_link($id)).'">Edit</a></p>';
    if(get_option('ff_previous_reading')){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="ff_restore">';wp_nonce_field('ff_restore');submit_button('Restore previous Reading settings','secondary');echo '</form>';}
    echo '<p><a href="'.esc_url(admin_url('options-general.php?page=fera-foundry-connections')).'">Configure email, AI, tawk.to and verification</a></p></div>';
}
function ff_connections_screen(){
    if(!current_user_can('manage_options'))return;
    echo '<div class="wrap"><h1>Fera Foundry connections</h1><form method="post" action="options.php">';settings_fields('ff_connections');
    foreach(['ff_email'=>'Enable email after testing authenticated SMTP','ff_ai'=>'Enable AI after configuring its server credential'] as $key=>$label)echo '<p><label><input type="checkbox" name="'.esc_attr($key).'" value="1" '.checked(get_option($key),'1',false).'> '.esc_html($label).'</label></p>';
    echo '<p><label>AI provider <select name="ff_provider">';foreach(['openai'=>'OpenAI','gemini'=>'Gemini'] as $key=>$label)echo '<option value="'.esc_attr($key).'" '.selected(get_option('ff_provider','openai'),$key,false).'>'.esc_html($label).'</option>';echo '</select></label></p><p>Set FERA_OPENAI_API_KEY or FERA_GEMINI_API_KEY server-side. No secrets are stored in these settings or browser code. Configure provider billing separately. AI conversations use the selected external provider; disclose that in your policy. No live provider tests were performed by this package.</p>';
    echo '<p><label>tawk.to integration owner <select name="ff_tawk_owner">';foreach(['none'=>'Not connected','theme'=>'Load once through Foundry on human handoff','external'=>'Use an existing tawk.to plugin/embed; do not load again'] as $key=>$label)echo '<option value="'.esc_attr($key).'" '.selected(get_option('ff_tawk_owner','none'),$key,false).'>'.esc_html($label).'</option>';echo '</select></label></p>';
    foreach(['ff_tawk_property'=>'Public tawk.to Property ID','ff_tawk_widget'=>'Public tawk.to Widget ID','ff_google_verification'=>'Google verification token','ff_bing_verification'=>'Bing verification token'] as $key=>$label)echo '<p><label>'.esc_html($label).' <input name="'.esc_attr($key).'" value="'.esc_attr(get_option($key,'')).'"></label></p>';
    submit_button();echo '</form><p>One floating entry point: Let’s Talk. Foundry hides the tawk.to launcher when ready and its own launcher during an active human conversation. Select external ownership when another plugin loads tawk.to. Test actual vendor behavior and cookie-notice placement on your host.</p><p>Email uses existing WordPress wp_mail/SMTP. No durable lead database or queue is added. SMTP acceptance is not mailbox delivery. Failed requests show retry/direct-contact instructions.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="ff_recover">';wp_nonce_field('ff_recover');submit_button('Recover stopped request locks','secondary');echo '</form><p>Recover only after confirming no mail/AI request remains active. Usage counters are preserved.</p></div>';
}
add_action('admin_post_ff_recover',function(){if(!current_user_can('manage_options'))wp_die('Not permitted.');check_admin_referer('ff_recover');delete_option('ff_busy_mail');delete_option('ff_busy_ai');wp_safe_redirect(admin_url('options-general.php?page=fera-foundry-connections'));exit;});
